package com.campuspulse.service.impl;
import com.campuspulse.service.AuthService;import com.campuspulse.repository.UserRepository;import com.campuspulse.security.JwtService;import com.campuspulse.entity.User;import com.campuspulse.enums.Role;import com.campuspulse.dto.request.Requests;import com.campuspulse.dto.response.Responses;import com.campuspulse.exception.ApiException;import org.springframework.http.HttpStatus;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class AuthServiceImpl implements AuthService{
private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt;
public AuthServiceImpl(UserRepository users,PasswordEncoder encoder,JwtService jwt){this.users=users;this.encoder=encoder;this.jwt=jwt;}
@Transactional public Responses.UserView signup(Requests.Signup r){if(users.existsByEmailIgnoreCase(r.email().trim()))throw new ApiException(HttpStatus.CONFLICT,"Email already registered");User u=new User();u.name=r.name().trim();u.email=r.email().trim().toLowerCase();u.password=encoder.encode(r.password());u.role=Role.STUDENT;return Responses.UserView.of(users.save(u));}
public Responses.AuthView login(Requests.Login r){User u=users.findByEmailIgnoreCase(r.email().trim()).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!encoder.matches(r.password(),u.password))throw new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password");return new Responses.AuthView(jwt.create(u.email),"Bearer",Responses.UserView.of(u));}
public User current(){var a=SecurityContextHolder.getContext().getAuthentication();if(a==null||!a.isAuthenticated())throw new ApiException(HttpStatus.UNAUTHORIZED,"Authentication required");return users.findByEmailIgnoreCase(a.getName()).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"User not found"));}
@Transactional public Responses.UserView update(Requests.Profile r){User u=current();u.name=r.name().trim();return Responses.UserView.of(users.save(u));}
}
